import { afterEach, describe, expect, it, vi } from 'vitest';
import { calculateCouponDiscount as calculatePublicDiscount, validateCouponCode } from '../../../task-a3-unit-tests/real/lib/coupons';
import { createCouponOrder } from '../../../task-a3-unit-tests/src/services/createCouponOrder';
import type { Coupon } from '../../../task-a3-unit-tests/src/domain/coupon';

const baseRecord = {
  id: 'coupon-1', code: 'SAVE', name: 'Save', description: null,
  discount_type: 'fixed', discount_value: 1000, minimum_amount: 0,
  maximum_discount: null, usage_limit: null, usage_count: 0,
  user_usage_limit: 1, valid_from: null, valid_until: null, is_active: true,
  applies_to_product_id: null,
};

function supabaseFake(data: any, usageCount = 0) {
  const couponQuery: any = {};
  couponQuery.select = vi.fn(() => couponQuery);
  couponQuery.eq = vi.fn(() => couponQuery);
  couponQuery.maybeSingle = vi.fn().mockResolvedValue({ data, error: null });
  let usageEqCount = 0;
  const usageQuery: any = {};
  usageQuery.select = vi.fn(() => usageQuery);
  usageQuery.eq = vi.fn(() => {
    usageEqCount += 1;
    return usageEqCount === 2 ? Promise.resolve({ count: usageCount, error: null }) : usageQuery;
  });
  const from = vi.fn((table: string) => table === 'coupons' ? couponQuery : usageQuery);
  return { client: { from } as any, from };
}

afterEach(() => { vi.useRealTimers(); vi.restoreAllMocks(); });

describe('A-3 coupon requirements', () => {
  it('calculates percentage and fixed discounts without exceeding the price', () => {
    expect(calculatePublicDiscount({ discount_type: 'percentage', discount_value: 20, maximum_discount: null }, 10000)).toBe(2000);
    expect(calculatePublicDiscount({ discount_type: 'fixed', discount_value: 15000, maximum_discount: null }, 10000)).toBe(10000);
  });

  it('applies numeric maximum_discount including zero', () => {
    expect(calculatePublicDiscount({ discount_type: 'percentage', discount_value: 50, maximum_discount: 2000 }, 10000)).toBe(2000);
    expect(calculatePublicDiscount({ discount_type: 'percentage', discount_value: 50, maximum_discount: 0 }, 10000)).toBe(0);
  });

  it.each([
    ['   ', 'user-1', { error: '쿠폰 코드를 입력해주세요.', status: 400 }],
    ['SAVE', '', { error: '로그인이 필요합니다.', status: 401 }],
  ])('rejects invalid input without DB lookup', async (code, userId, expected) => {
    const from = vi.fn();
    await expect(validateCouponCode({ supabase: { from } as any, code, subtotal: 10000, userId })).resolves.toEqual(expected);
    expect(from).not.toHaveBeenCalled();
  });

  it('rejects a coupon that does not exist', async () => {
    const { client } = supabaseFake(null);
    await expect(validateCouponCode({ supabase: client, code: 'NONE', subtotal: 10000, userId: 'user-1' })).resolves.toEqual({ error: '유효하지 않은 쿠폰 코드입니다.', status: 404 });
  });

  it('rejects an expired coupon at a fixed time', async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2026-08-17T12:00:00+09:00'));
    const { client } = supabaseFake({ ...baseRecord, valid_until: '2026-08-16' });
    await expect(validateCouponCode({ supabase: client, code: 'SAVE', subtotal: 10000, userId: 'user-1' })).resolves.toEqual({ error: '만료된 쿠폰입니다.', status: 400 });
  });

  it('accepts minimum amount equality and rejects one won below', async () => {
    const equal = supabaseFake({ ...baseRecord, minimum_amount: 10000 });
    const accepted = await validateCouponCode({ supabase: equal.client, code: 'SAVE', subtotal: 10000, userId: 'user-1' });
    expect(accepted).toMatchObject({ discountAmount: 1000, finalAmount: 9000 });

    const below = supabaseFake({ ...baseRecord, minimum_amount: 10000 });
    await expect(validateCouponCode({ supabase: below.client, code: 'SAVE', subtotal: 9999, userId: 'user-1' })).resolves.toEqual({ error: '최소 주문 금액 10,000원 이상이어야 합니다.', status: 400 });
  });

  it('rejects when the user usage count reaches user_usage_limit', async () => {
    const { client } = supabaseFake({ ...baseRecord, user_usage_limit: 1 }, 1);
    await expect(validateCouponCode({ supabase: client, code: 'SAVE', subtotal: 10000, userId: 'user-1' })).resolves.toEqual({ error: '이미 사용 한도를 채운 쿠폰입니다.', status: 400 });
  });

  it('uses the real domain calculation while mocking only external ports', async () => {
    const coupon: Coupon = { code: 'P20', type: 'PERCENTAGE', value: 20, minOrderAmount: 0, expiresAt: new Date('2026-12-31T00:00:00Z'), isActive: true };
    const couponRepository = { findByCode: vi.fn().mockResolvedValue(coupon) };
    const paymentGateway = { requestPayment: vi.fn().mockResolvedValue({ approved: true, approvedAmount: 8000 }) };
    const orderRepository = { save: vi.fn(async (order) => order) };
    const order = await createCouponOrder({ orderId: 'order-1', productCode: 'P1', productPrice: 10000, couponCode: 'P20', now: new Date('2026-08-17T00:00:00Z'), couponRepository, paymentGateway, orderRepository });
    expect(paymentGateway.requestPayment).toHaveBeenCalledWith({ orderId: 'order-1', amount: 8000 });
    expect(order).toMatchObject({ discountAmount: 2000, finalAmount: 8000, status: 'PAID', downloadGranted: true });
  });
});
